 */
function meaningfulBody(raw) {
  let s = String(raw == null ? '' : raw);
  s = s.replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]+>/g, ' ');
  s = s
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#3?9;/gi, "'");

  const kept = [];
  for (const line of s.split(/\r?\n/)) {
    const t = line.trim();
    if (!t) continue;
    if (/^>/.test(t)) continue;
    if (/^(-{2,}|_{3,}|\*{3,})\s*$/.test(t)) break;
    if (/^(on\s.+\swrote:|el\s.+\sescribió:|am\s.+\sschrieb:|-{2,}\s*(original message|forwarded message|mensaje original))/i.test(t)) break;
    kept.push(t);
  }
  return kept.join(' ').replace(/\s+/g, ' ').trim();
}

/**
 * Is this machine-generated mail rather than someone asking for a quote?
 *
 * Returns a reason string, or null when the message looks human. Applied on EVERY route, not just
 * the open one: an out-of-office was never a valid RFQ on any address, and turning one into a
 * proposal is a bug wherever it happens.
 */
function detectAutomated({ headers, subject, senderEmail }) {
  const h = headers || {};

  // RFC 3834: 'no' is the only value that means "a person sent this".
  const autoSubmitted = String(h['auto-submitted'] || '').trim().toLowerCase();
  if (autoSubmitted && autoSubmitted !== 'no') return 'auto_submitted';

  for (const name of AUTOMATED_HEADERS) {
    if (h[name] != null && String(h[name]).trim() !== '') return 'automated_header';
  }

  const precedence = String(h.precedence || '').trim().toLowerCase();
  if (BULK_PRECEDENCE.includes(precedence)) return 'bulk_precedence';

  // A null return-path is the signature of a bounce / delivery status notification.
  const returnPath = String(h['return-path'] || '').trim();
  if (returnPath === '<>' || returnPath === '') {
    if (returnPath === '<>') return 'bounce';
  }

  if (AUTOMATED_SUBJECT_RE.test(String(subject || ''))) return 'automated_subject';

  const localPart = String(senderEmail || '').split('@')[0];
  if (localPart && NOREPLY_LOCALPART_RE.test(localPart)) return 'noreply_sender';

  return null;
}

/**
 * Run every intake guard over one message and say what should happen to it.
 *
 * `counters` is the persisted daily tally — `{ day, by_sender, open_total }`. In n8n it is
 * `$getWorkflowStaticData('global')`; in the self-check it is a plain object. It is mutated in
 * place, and ONLY when a message is accepted, so a rejected message never consumes quota.
 *
 * Returns:
 *   { accepted: false, drop: true,  reason, notify: false }  junk — swallow it silently. A spam
 *                                                            wave must not become a Telegram flood.
 *   { accepted: false, drop: false, reason, notify: true }   refused, and Mark should know.
 *   { accepted: true,  text, truncated, ... }                proceed; `text` may be truncated.
 */
function classifyIntake({
  intake,
  senderEmail,
  subject,
  text,
  headers,
  sizeBytes,
  attachmentCount,
  counters,
  today,
  limits,
}) {
  const lim = Object.assign({}, INTAKE_LIMITS, limits || {});
  const route = (intake && intake.route) || 'registry';
  const open = !!(intake && intake.open);
  const sender = senderEmail ? String(senderEmail).toLowerCase() : null;

  const drop = (reason) => ({ accepted: false, drop: true, notify: false, reason, route, open });
  const refuse = (reason, detail) => ({ accepted: false, drop: false, notify: true, reason, detail: detail || '', route, open, sender_email: sender });

  // --- 1. junk filter (every route) ----------------------------------------
  const automated = detectAutomated({ headers, subject, senderEmail: sender });
  if (automated) return drop(automated);

  const body = meaningfulBody(text);
  if (body.length < lim.min_body_chars) return drop('empty_body');

  // --- everything below guards the PUBLIC address only ----------------------
  // A registered client on proposal@ is paying for throughput and is not metered.
  if (!open) {
    return { accepted: true, drop: false, notify: false, route, open, sender_email: sender, text: String(text == null ? '' : text), truncated: false, body_chars: body.length };
  }

  // The reply to a public RFQ goes to whoever sent it. With no parseable sender there is nobody
  // to reply to, and Module 4 would throw much further downstream after all the spend.
  if (!sender) return refuse('no_sender', 'open intake with no parseable From address');

  // --- 2. size / attachment cap --------------------------------------------
  const bytes = Number(sizeBytes) || 0;
  if (bytes > lim.max_email_bytes) {
    return refuse('oversize', `${Math.round(bytes / 1024)} KB over the ${Math.round(lim.max_email_bytes / 1024)} KB cap`);
  }
  const attachments = Number(attachmentCount) || 0;
  if (attachments > lim.max_attachments) {
    return refuse('too_many_attachments', `${attachments} attachments over the ${lim.max_attachments} cap`);
  }

  // --- 3. rate limit, per sender and overall --------------------------------
  const day = today || new Date().toISOString().slice(0, 10);
  if (counters.day !== day) {
    counters.day = day;
    counters.by_sender = {};
    counters.open_total = 0;
  }
  if (!counters.by_sender) counters.by_sender = {};
  if (typeof counters.open_total !== 'number') counters.open_total = 0;

  const usedBySender = counters.by_sender[sender] || 0;
  if (usedBySender >= lim.max_rfq_per_sender_per_day) {
    return refuse('rate_limited_sender', `${usedBySender} already today, cap ${lim.max_rfq_per_sender_per_day}`);
  }
  if (counters.open_total >= lim.max_open_rfq_per_day) {
    return refuse('rate_limited_global', `${counters.open_total} public RFQs already today, cap ${lim.max_open_rfq_per_day}`);
  }

  // --- 4. body cap: truncate, do not refuse ---------------------------------
  const raw = String(text == null ? '' : text);
  let outText = raw;
  let truncated = false;
  if (raw.length > lim.max_body_chars) {
    outText = `${raw.slice(0, lim.max_body_chars)}\n\n[intake guard: truncated ${raw.length - lim.max_body_chars} characters over the ${lim.max_body_chars}-character cap]`;
    truncated = true;
  }

  // Quota is spent only by a message that is actually going to be processed.
  counters.by_sender[sender] = usedBySender + 1;
  counters.open_total += 1;

  return {
    accepted: true,
    drop: false,
    notify: false,
    route,
    open,
    sender_email: sender,
    text: outText,
    truncated,
    body_chars: body.length,
    sender_count_today: counters.by_sender[sender],
    open_total_today: counters.open_total,
  };
}
// === INTAKE CORE END ===

// --- n8n wrapper ---
// The intake guards, run BEFORE the registry read and BEFORE Module 1 — the only place they are
// worth anything, because every node after them costs LLM tokens or Drive calls.
//
//   junk filter   -> silent drop: autoresponders, bounces, mailing lists, empty bodies
//   size cap      -> refused + Telegram
//   rate limit    -> refused + Telegram (per sender per day, plus a ceiling for the address)
//   body cap      -> truncated, never refused
//
// Registered clients on proposal@ pass everything but the junk filter: they are paying for
// throughput, and metering them would be a regression. Only the public address is capped.
//
// SOURCE OF TRUTH mirrored in modules/intake/intake_core.js — change both, and check with
// `node modules/intake/intake_core.js`.
const env = $('Build Envelope').first().json;
const meta = env.email_meta || {};

// The daily tally lives in the workflow's own static data — n8n persists it after each
// production execution, so a counter this small needs no external store. Two honest caveats:
// it is per workflow (a second orchestrator would keep its own count), and two executions
// overlapping within the same tick can both read the pre-increment value. Acceptable for a cap
// whose job is to bound a bill; it is not a security boundary.
const counters = $getWorkflowStaticData('global');

const verdict = classifyIntake({
  intake: env.intake,
  senderEmail: env.sender_email,
  subject: (env.data && env.data.subject) || '',
  text: (env.data && env.data.text) || '',
  headers: meta.headers,
  sizeBytes: meta.size_bytes,
  attachmentCount: meta.attachment_count,
  counters,
  today: $now.toUTC().toFormat('yyyy-MM-dd'),
});

// Junk: return no items at all. The branch simply ends, with no Telegram alert — deliberate,
// because a spam wave must not become a notification flood. The n8n execution log still shows
// the drop and its reason.
if (verdict.drop) {
  console.log(`Intake Guard: dropped (${verdict.reason}) from ${env.sender_email || 'unknown sender'}`);
  return [];
}

if (!verdict.accepted) {
  return [{ json: {
    accepted: false,
    resolved: false,
    reason: verdict.reason,
    detail: verdict.detail || '',
    sender_email: verdict.sender_email || env.sender_email || null,
    intake_address: (env.intake && env.intake.address) || null,
    data: env.data
  } }];
}

// Accepted. `data.text` is the guard's own copy — byte-identical to the original unless the body
// cap truncated it — so nothing downstream can spend more than the cap's worth of tokens.
return [{ json: {
  accepted: true,
  sender_email: env.sender_email,
  intake: env.intake,
  email_context: env.email_context,
  truncated: !!verdict.truncated,
  sender_count_today: verdict.sender_count_today || null,
  open_total_today: verdict.open_total_today || null,
  data: { subject: (env.data && env.data.subject) || 'RFQ', text: verdict.text }
} }];

// Resolve the client ONCE from the registry, enforcing Client Status. WHICH KEY is used depends
// on the intake the message came through (decided in 'Build Envelope'):
//   open route (demo@cifral.io)      -> the client is FIXED to demo_client, whoever wrote in.
//                                       Nothing about the sender is consulted — that is the point.
//   registry route (proposal@, etc.) -> the SENDER's address must match a row's
//                                       commercial_contact_email, or the RFQ is rejected as before.
// The n8n Notion node flattens properties as 'property_<snake_case>'.
// Outputs resolved:true (proceed) or resolved:false (rejected) — 'Client OK?' branches on it.
//   - unknown_sender:        no registry row matches the sender email (registry route only).
//   - inactive:              the matched client is 'paused' or 'churned'.
//   - demo_tenant_missing:   the open route resolved but demo_client has no registry row.
//   - open_intake_misrouted: the open route matched a row that is not the demo tenant.
const DEMO_CLIENT_ID = 'demo_client';
const env = $('Build Envelope').first().json;
const guard = $('Intake Guard').first().json;
const intake = guard.intake || env.intake || { route: 'registry', open: false, client_id: null };
const senderEmail = (env.sender_email || '').toLowerCase();
const fallbackId = env.fallback_client_id;
// The guard's copy of the message: identical to the original unless the body cap truncated it.
const data = guard.data || env.data;
const rows = $input.all();
// Notion hands each property over in whatever shape n8n's node uses for that property type. The
// previous prop() ended in `?? p ?? null`, so an unrecognised shape leaked out as the RAW OBJECT
// and every downstream string comparison failed SILENTLY. Two of those failures were live: a
// Select ({name:'proposal_only'}) never matched a tier, and an EMPTY rich_text arrived as [] or
// {} — both truthy — so "no pricing_sheet_id" read as "pricing configured". Together they routed
// a proposal_only client into Module 3. Normalise to a string or null; booleans pass through.
function asText(v){ if(v==null) return ''; if(typeof v==='string') return v.trim(); if(typeof v==='number'||typeof v==='boolean') return String(v); if(Array.isArray(v)) return v.map(asText).filter(Boolean).join(' ').trim(); if(typeof v==='object') return asText(v.name ?? v.value ?? v.plain_text ?? v.content ?? (v.select&&v.select.name) ?? (v.status&&v.status.name) ?? v.text ?? ''); return ''; }
function prop(props, name){ const p = props && props[name]; if(typeof p==='boolean') return p; const t = asText(p); return t === '' ? null : t; }
let match=null;
if(intake.open){
  for(const r of rows){ const props=r.json.properties||r.json; if(prop(props,'property_client_id')===intake.client_id){ match=props; break; } }
  if(!match){ return [{ json: { resolved:false, reason:'demo_tenant_missing', client_id: intake.client_id, sender_email: senderEmail||null, intake_address: intake.address||null, data } }]; }
} else {
  for(const r of rows){ const props=r.json.properties||r.json; const email=String(prop(props,'property_commercial_contact_email')||'').toLowerCase(); const cid=prop(props,'property_client_id'); if(senderEmail && email && email===senderEmail){ match=props; break; } if(!senderEmail && fallbackId && cid===fallbackId){ match=props; break; } }
  if(!match){ return [{ json: { resolved:false, reason:'unknown_sender', sender_email: senderEmail||null, intake_address: intake.address||null, data } }]; }
}
const clientStatus = prop(match,'property_client_status');
const wantId = prop(match,'property_client_id');
if(clientStatus==='paused' || clientStatus==='churned'){ return [{ json: { resolved:false, reason:'inactive', client_id: wantId, client_status: clientStatus, sender_email: senderEmail||null, intake_address: intake.address||null, data } }]; }

// Guard 5 backstop. The open route must resolve to the demo tenant and nothing else. If the
// registry is ever edited so that this lookup lands on another row, a stranger would be served
// that client's template, clause library and rate card — so it stops here instead.
if(intake.open && wantId !== DEMO_CLIENT_ID){ return [{ json: { resolved:false, reason:'open_intake_misrouted', client_id: wantId, sender_email: senderEmail||null, intake_address: intake.address||null, data } }]; }

// Outbound identity. 'trial' clients send from the demo address so pilot traffic stays
// visibly separate from production. Both must be VERIFIED 'Send mail as' aliases on the
// Gmail account that owns the credential, or Gmail rejects drafts.send.
// Keep in sync with 04-proposal-assembly.json -> 'Map Client Config' (standalone fallback).
const DEMO_FROM_ALIAS = 'demo@cifral.io';
const PROD_FROM_ALIAS = 'proposal@cifral.io';
function resolveFromAlias(status){ return status === 'trial' ? DEMO_FROM_ALIAS : PROD_FROM_ALIAS; }
// send_mode is the per-client kill switch: 'send' delivers the reply, 'draft' only parks it
// in the mailbox (the pre-production behaviour). Anything other than 'draft' means 'send'.
function resolveSendMode(raw){ return String(raw || 'send').trim().toLowerCase() === 'draft' ? 'draft' : 'send'; }

// GUARD 1 — THE ONE PLACE the demo tenant's delivery mode is decided.
//
// It is decided here in code rather than read from the registry, and that has not changed. The
// registry read is the failure class that has already cost this system two incidents: a property
// that is renamed, blanked or mistyped does not raise, it yields undefined, and
// `String(undefined || 'send')` resolves undefined to whatever the default happens to be. A
// public address cannot have its behaviour decided by an accident, in EITHER direction — so on
// this path there is no registry value and no default to fall back to.
//
// What changed (2026-08-18) is the value, not the mechanism. DEMO_SEND_MODE arrives from
// modules/intake/intake_core.js through 'Build Envelope', and is 'send': the whole point of
// demo@cifral.io is that a prospect emails an RFQ and gets the sample proposal back by itself.
// Every gate downstream now READS the send_mode resolved here instead of re-deriving 'draft'
// from open_intake, so flipping that one constant back to 'draft' takes the address quiet again.
//
// An envelope with no answer on it is a 'Build Envelope' older than this change — someone
// re-imported one workflow and not the other. That resolves to 'draft', not 'send': the rule is
// still that an accident may not decide what a public address does, and of the two ways to be
// wrong, a demo that has gone quiet announces itself in Telegram while a demo that sends when it
// should not does its announcing in a stranger's inbox.
const DEMO_SEND_MODE = intake.demo_send_mode === 'send' ? 'send' : 'draft';
const isDemoTenant = intake.open || wantId === DEMO_CLIENT_ID;
const send_mode = isDemoTenant ? DEMO_SEND_MODE : resolveSendMode(prop(match,'property_send_mode'));

const client_config = {
  client_id: wantId,
  client_name: prop(match,'property_client_name'),
  status: clientStatus,
  service_tier: prop(match,'property_service_tier'),
  commercial_contact_email: prop(match,'property_commercial_contact_email'),
  reply_to: senderEmail || prop(match,'property_commercial_contact_email'),
  templates: { en: prop(match,'property_template_id_en'), es: prop(match,'property_template_id_es') },
  proposals_folder_id: prop(match,'property_proposals_folder_id'),
  reference_docs_folder_id: prop(match,'property_reference_docs_folder_id'),
  pricing_sheet_id: prop(match,'property_pricing_sheet_id'),
  proposal_config_sheet_id: prop(match,'property_proposal_config_sheet_id'),
  notification_chat_id: prop(match,'property_notification_chat_id'),
  from_alias: resolveFromAlias(clientStatus),
  send_mode,
  // Travels with the envelope so the last gate before Gmail knows this reply is answering a
  // stranger — which decides the wording of the mail, not any more whether it goes out.
  open_intake: !!intake.open,
  // The demo tenant whichever route it came in on, so Module 4 can label the document and the
  // covering email as a demonstration without having to re-derive it from the client id.
  demo_tenant: !!isDemoTenant,
  intake_address: intake.address || null
};
return [{ json: { resolved:true, client_id: wantId, client_config, sender_email: senderEmail||null, email_context: env.email_context || null, data, status: 'ok', errors: [] } }];

