parameters.jsCode:
// Decide what to produce.
//
// `service_tier` is the CEILING, not merely a default. It is what the client contracted for, so a
// single request may narrow WITHIN it — README: "a client on full_pipeline can still ask for just
// a price on a given RFQ" — but may never widen past it. request_type comes from an LLM reading
// free text; its prompt says to prefer 'unspecified' over guessing, but that is a judgement call,
// not a guarantee, so the tier bounds it rather than trusting it.

// --- normalise whatever the registry handed over --------------------------------------------
// 'Map Client Config' passes Notion values through its prop() helper, which ends in `?? p ?? null`
// — so any property shape it does not recognise leaks out as the RAW OBJECT. A Select arriving as
// {name:'proposal_only'} instead of 'proposal_only' then fails every string comparison here
// SILENTLY, and fails toward 'full_pipeline' because that is the fallback. Nobody noticed while
// the only live client was full_pipeline anyway. Never trust the shape; normalise it.
function asText(v) {
  if (v == null) return '';
  if (typeof v === 'string') return v.trim();
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  if (Array.isArray(v)) return v.map(asText).filter(Boolean).join(' ').trim();
  if (typeof v === 'object') {
    return asText(v.name ?? v.value ?? v.plain_text ?? v.content
      ?? (v.select && v.select.name) ?? (v.status && v.status.name) ?? v.text ?? '');
  }
  return '';
}
// 'Proposal Only', 'proposal-only' and {name:'proposal_only'} are all the same tier.
const slug = (v) => asText(v).toLowerCase().replace(/[\s-]+/g, '_');

const TIER_ALLOWS = {
  pricing_only: ['pricing_only'],
  proposal_only: ['proposal_only'],
  full_pipeline: ['pricing_only', 'proposal_only', 'full_pipeline'],
};

const j = $json;
const cfg = j.client_config || {};

const service_tier_raw = cfg.service_tier ?? null;
const tierSlug = slug(service_tier_raw);
const tier = TIER_ALLOWS[tierSlug] ? tierSlug : 'full_pipeline';

const requested_route = slug(j.data && j.data.request_type) || 'unspecified';

const notes = [];
// A tier that arrived but did not parse is a registry problem, and it fails PERMISSIVE — say so
// loudly rather than quietly serving full_pipeline.
if (asText(service_tier_raw) && !TIER_ALLOWS[tierSlug]) {
  notes.push(`service_tier from the registry read as ${JSON.stringify(service_tier_raw)}, which is not one of pricing_only / proposal_only / full_pipeline — treated as 'full_pipeline'. Check the Notion property.`);
}

// Anything the tier does not permit — including 'unspecified' — falls back to the tier itself.
let route = TIER_ALLOWS[tier].includes(requested_route) ? requested_route : tier;
if (requested_route !== 'unspecified' && route !== requested_route) {
  notes.push(`The request read as '${requested_route}', which is outside this client's '${tier}' tier — delivered '${route}'.`);
}

// CAPABILITY BACKSTOP. After the clamp, a pricing route can only appear because the TIER says so,
// which makes this purely a misconfiguration check. Note asText(): an empty rich_text property can
// arrive as [] or {}, both TRUTHY, so a bare `cfg.pricing_sheet_id ||` would read "no sheet id" as
// "sheet id present" — the same shape-blindness this file just had to defend against above.
const has_pricing = !!asText(cfg.pricing_sheet_id) || !!cfg.rate_card;
if ((route === 'full_pipeline' || route === 'pricing_only') && !has_pricing) {
  if (route === 'full_pipeline') {
    // The document is still fully deliverable — it just loses the commercial section.
    route = 'proposal_only';
    notes.push(`Tier is 'full_pipeline' but '${j.client_id}' has no pricing configured (no pricing_sheet_id) — delivered 'proposal_only'. See docs/PRICING-SHEET-TEMPLATE.md.`);
  } else {
    // A price is the ENTIRE deliverable here, so there is nothing to degrade to.
    route = 'blocked_no_pricing';
    notes.push(`Tier is 'pricing_only' but '${j.client_id}' has no pricing configured (no pricing_sheet_id) — nothing could be produced. See docs/PRICING-SHEET-TEMPLATE.md.`);
  }
}

// service_tier_raw and has_pricing are echoed so the next time this misroutes, the node's own
// output says why — without adding a debug node or reading another workflow's execution.
return [{ json: {
  ...j,
  route,
  requested_route,
  service_tier: tier,
  service_tier_raw,
  has_pricing,
  route_note: notes.length ? notes.join(' ') : null,
} }];

// Manual pricing estimate (phase 1 has NO auto hours-estimation engine — explicit non-goal).
// The representative estimate is FILTERED by the request's scope_of_supply: out-of-scope
// categories are dropped so the quote only prices what we're actually supplying.
// scope->cost-category mapping mirrors schemas/scope-catalog.json.
const j = $json;
const scope = (j.data && j.data.scope_of_supply) || {};
const ALL_HOURS = { engineering: 40, assembly: 60, commissioning: 20, project_management: 15 };
const GATE = { engineering: scope.engineering, assembly: scope.installation, commissioning: scope.commissioning, project_management: scope.project_management };
const hours_by_category = {};
for (const k of Object.keys(ALL_HOURS)) { if (GATE[k]) hours_by_category[k] = ALL_HOURS[k]; }
const materials_cost = scope.materials ? 5000 : 0;
return [{ json: { client_id: j.client_id, client_config: j.client_config, data: { materials_cost, hours_by_category } } }];

// pricing_only deliverable: a price estimate (no proposal document). Draft goes to the
// client's own commercial contact (G1), never the extracted end customer.
const j = $json; // Module 3 output: { client_id, client_config, data:<pricing> }
// client_config rides through Module 3 untouched; fall back to the orchestrator's own
// resolution if a future change ever drops it, so the alias can never silently go missing.
const cfg = j.client_config || $('Map Client Config').first().json.client_config || {};
const ec = $('Build Envelope').first().json.email_context || {};
const p = j.data || {};
const recipient = cfg.reply_to || cfg.commercial_contact_email;
if (!recipient) throw new Error(`No reply address for '${j.client_id}' (sender email + commercial_contact_email both empty). Refusing to send the quote to the end customer (gap G1).`);
const m1 = $('Call Module 1').first().json;
const company = (m1.data && m1.data.client && m1.data.client.company) || 'Client';
const cur = p.currency || '';
// Reply inside the reseller's own RFQ thread. Gmail only threads when the threadId AND the
// subject match the original, so a synthetic subject would break out into a new conversation.
const subject = ec.reply_subject || `Price estimate — ${company}`;

// A pricing_only answer to a public RFQ is a demonstration, and it says so. The reseller version
// prints the internal SUBTOTAL — that is the pre-margin cost basis, deliberately absent from the
// document itself — so the demo version must not, because on this route the reader is the
// customer rather than the reseller.
const isDemo = cfg.demo_tenant === true || cfg.open_intake === true || j.client_id === 'demo_client';
const lang = ((($('Call Module 1').first().json.data || {}).rfq || {}).language === 'es') ? 'es' : 'en';
const esc = (v) => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const money = (v) => `${esc(v)} ${esc(cur)}`;
const html = isDemo
  ? (lang === 'es'
    ? `<p>Hola,</p>\n<p>Esta es la <b>estimación de precio de muestra</b> generada automáticamente a partir de su solicitud:</p>\n<ul>\n<li><b>Total: ${money(p.total)}</b></li>\n<li>Condiciones de pago: ${esc(p.payment_terms || '')}</li>\n</ul>\n<p><b>Es una demostración.</b> Los importes salen de una tarifa de ejemplo, no son una oferta y no son vinculantes. En una implantación se calculan con la tarifa y las reglas de márgenes de su empresa, desde su propia hoja de cálculo.</p>\n<p>Si quiere probarlo con su tarifa real, respóndanos a este correo.</p>\n<p>Un saludo<br>Cifral</p>`
    : `<p>Hello,</p>\n<p>Here is the <b>sample price estimate</b> generated automatically from your request:</p>\n<ul>\n<li><b>Total: ${money(p.total)}</b></li>\n<li>Payment terms: ${esc(p.payment_terms || '')}</li>\n</ul>\n<p><b>This is a demonstration.</b> The figures come from an example rate card, they are not an offer and they are not binding. In a live setup they are computed from your own rate card and margin rules, out of your own spreadsheet.</p>\n<p>If you would like to try it against your real rate card, just reply to this email.</p>\n<p>Kind regards<br>Cifral</p>`)
  : `<p>Hi,</p>\n<p>Here is the price estimate for <b>${esc(company)}</b>, for your review before it goes to the customer.</p>\n<ul>\n<li>Subtotal: ${money(p.subtotal)}</li>\n<li><b>Total: ${money(p.total)}</b></li>\n<li>Payment terms: ${esc(p.payment_terms || '')}</li>\n</ul>\n<p>Priced items: ${(p.priced_categories||[]).join(', ') || 'materials'}.</p>`;
const from_alias = cfg.from_alias || '';
if (!from_alias) throw new Error(`No from_alias resolved for '${j.client_id}'. Refusing to send from the raw mailbox address.`);
// Empty string (not null) for threadId: the Gmail node treats it as falsy and omits the
// field, whereas a null would be serialised into the API call.
// GUARD 1, last gate before Gmail. 'Map Client Config' is the ONE place the mode is decided —
// for the demo tenant from DEMO_SEND_MODE, for everyone else from their registry row — so this
// gate no longer re-derives it. What it still does is fail CLOSED: anything that is not the
// literal 'send' parks the message as a draft, so a lost or garbled value can only ever cost a
// delivery, never buy one.
const send_mode = String(cfg.send_mode || '').trim().toLowerCase() === 'send' ? 'send' : 'draft';
return [{ json: { client_id: j.client_id, recipient, notification_chat_id: cfg.notification_chat_id, client_status: cfg.status || '', from_alias, send_mode, thread_id: ec.thread_id || '', subject, html, company, total: p.total, currency: cur, demo_tenant: isDemo } }];

