parameters.jsCode:
// An incomplete RFQ is not a system error — it is a conversation. The sender left something out,
// and only they can supply it, so the useful place for that message is their inbox rather than
// Cifral's Telegram. This composes that reply; 'RFQ Needs Review' still fires for Cifral either way.
//
// Recipient is the ACTUAL SENDER, never the extracted end customer — the same G1 rule the proposal
// and the quote follow. Reply goes into the original thread: Gmail threads on threadId AND a
// matching subject, so the subject has to be the original one prefixed with 'Re: '.
const m1 = $('Call Module 1').first().json;
const cfg = m1.client_config || $('Map Client Config').first().json.client_config || {};
const ec = $('Build Envelope').first().json.email_context || {};
const data = m1.data || {};

const recipient = cfg.reply_to || cfg.commercial_contact_email || '';
const from_alias = cfg.from_alias || '';
const lang = data.language === 'es' ? 'es' : 'en';

// GUARD 1, last gate before Gmail, exactly as Module 4 and the quote branch do it. The mode was
// resolved once in 'Map Client Config'; this gate only fails CLOSED on anything that is not the
// literal 'send'. Asking a prospect for the one field they left out is the most useful message
// this system sends — holding it as a draft until a human notices is what made the demo feel dead.
const send_mode = String(cfg.send_mode || '').trim().toLowerCase() === 'send' ? 'send' : 'draft';

// Labels come from Module 1, which knows both the standard field names and — for the client's own
// declared fields — the exact label their Fields tab told the sender to write.
const detail = Array.isArray(data.missing_fields_detail) && data.missing_fields_detail.length
  ? data.missing_fields_detail
  : (data.missing_fields || []).map((k) => ({ key: k, label: k }));

const company = (data.client && data.client.company) || '';
const T = {
  es: {
    subject: ec.reply_subject || `Falta información para preparar la propuesta${company ? ' — ' + company : ''}`,
    intro: 'Gracias por su solicitud. Para poder preparar la propuesta necesitamos algunos datos que no hemos localizado en su mensaje:',
    outro: 'Puede responder a este mismo correo indicando esa información y continuaremos con la propuesta.',
    hello: 'Hola,', bye: 'Un saludo',
  },
  en: {
    subject: ec.reply_subject || `Missing information to prepare the proposal${company ? ' — ' + company : ''}`,
    intro: 'Thank you for your request. Before we can prepare the proposal we need a few details we could not find in your message:',
    outro: 'Just reply to this email with that information and we will carry on with the proposal.',
    hello: 'Hello,', bye: 'Kind regards',
  },
}[lang];

const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = `<p>${T.hello}</p>\n<p>${T.intro}</p>\n<ul>\n${detail.map((d) => `<li>${esc(d.label)}</li>`).join('\n')}\n</ul>\n<p>${T.outro}</p>\n<p>${T.bye}</p>`;

return [{ json: {
  client_id: m1.client_id,
  recipient,
  from_alias,
  send_mode,
  thread_id: ec.thread_id || '',
  subject: T.subject,
  html,
  missing_count: detail.length,
  // Reported rather than thrown: 'RFQ Needs Review' has already alerted a human by the time this
  // runs, and throwing here would turn a missing address into a failed execution on top of it.
  deliverable: !!(recipient && from_alias),
} }];
